CREATE TABLE `rutinas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `tipo` varchar(255) NOT NULL,
  `grupo` varchar(255) NOT NULL,
  `segmento` varchar(255) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `ejercicio_id` bigint(20) unsigned DEFAULT NULL,
  `series` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`series`)),
  `descanso_valor` varchar(10) DEFAULT NULL,
  `descanso_unidad` varchar(10) DEFAULT 'seg',
  `nota_sesion` text DEFAULT NULL,
  `nota_ej` text DEFAULT NULL,
  `orden` int(10) unsigned NOT NULL DEFAULT 0,
  `entrenamiento` varchar(255) DEFAULT NULL,
  `semana` int(11) DEFAULT NULL,
  `dia` int(11) DEFAULT NULL,
  `fecha` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rutinas_user_id_foreign` (`user_id`),
  CONSTRAINT `rutinas_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3016 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
